// Never echo the failing payload: it may contain caller utterances, and this
// message lands in Slack (I6). Identify the workflow and the node, nothing more.
const e = $input.first().json;
const wf = e.workflow || {};
const ex = e.execution || {};
return [{ json: {
  text: [
    ':rotating_light: *n8n workflow failed*',
    '*Workflow:* ' + (wf.name || 'unknown'),
    '*Node:* ' + (ex.lastNodeExecuted || 'unknown'),
    '*Error:* ' + String(ex.error?.message || 'unknown').slice(0, 300),
    '*Execution:* ' + (ex.id || 'n/a')
  ].join('\n')
} }];
